args.command:
node -e "
import('./src/parse.js').then(m => {
  console.log('parse 10:', JSON.stringify(m.parseTask({id:'a', priority:' 10 '})));
  console.log('parse soon:', JSON.stringify(m.parseTask({id:'x', priority:'soon'})));
  console.log('parse -3:', JSON.stringify(m.parseTask({id:'x', priority:'-3'})));
});
import('./src/compare.js').then(m => {
  console.log('compare str 10 vs 2:', m.compare({priority:'10'},{priority:'2'}));
  console.log('compare num 10 vs 2:', m.compare({priority:10},{priority:2}));
});
"

node -e "
import('./src/scheduler.js').then(m => {
  console.log('runOrder:', JSON.stringify(m.runOrder([
    { id: 'a', priority: '2' },
    { id: 'b', priority: '10' },
    { id: 'c', priority: '1' },
  ])));
});
"

node --input-type=module -e "
import { parseTask } from './src/parse.js';
import { compare } from './src/compare.js';
import { runOrder } from './src/scheduler.js';
console.log('parse 10:', JSON.stringify(parseTask({id:'a', priority:' 10 '})), typeof parseTask({id:'a', priority:' 10 '}).priority);
console.log('parse soon:', JSON.stringify(parseTask({id:'x', priority:'soon'})));
console.log('parse -3:', JSON.stringify(parseTask({id:'x', priority:'-3'})));
console.log('compare str 10 vs 2:', compare({priority:'10'},{priority:'2'}));
console.log('compare num 10 vs 2:', compare({priority:10},{priority:2}));
console.log('runOrder:', JSON.stringify(runOrder([{id:'a',priority:'2'},{id:'b',priority:'10'},{id:'c',priority:'1'}])));
"

cat > /tmp/probe.mjs <<'EOF'
import { parseTask } from './src/parse.js';
import { compare } from './src/compare.js';
import { runOrder } from './src/scheduler.js';
console.log('parse 10:', JSON.stringify(parseTask({id:'a', priority:' 10 '})), typeof parseTask({id:'a', priority:' 10 '}).priority);
console.log('parse soon:', JSON.stringify(parseTask({id:'x', priority:'soon'})));
console.log('parse -3:', JSON.stringify(parseTask({id:'x', priority:'-3'})));
console.log('compare str 10 vs 2:', compare({priority:'10'},{priority:'2'}));
console.log('compare num 10 vs 2:', compare({priority:10},{priority:2}));
console.log('runOrder:', JSON.stringify(runOrder([{id:'a',priority:'2'},{id:'b',priority:'10'},{id:'c',priority:'1'}])));
EOF
node /tmp/probe.mjs
